/**
 * Keycloak plugin
 *
 * Manages Keycloak servers, realms, clients and redirect URIs.
 * Allows operators to:
 *   - Add/configure Keycloak servers (realms/clients auto-discovered)
 *   - Create/rename/delete realms and clients — REAL Keycloak writes
 *     (clients are confidential OIDC, secret generated by Keycloak and stored)
 *   - View and manage redirect + post-logout URIs in Keycloak
 *   - Register/unregister an instance's URLs via the orchestrator (nbdiu)
 *
 * Configuration:
 *   - No environment variables needed
 *   - All config is stored in the database
 *
 * Tables (each child cascades on delete):
 *   - plugin_keycloak_server: Keycloak servers (URL + admin credentials)
 *   - plugin_keycloak_realm: realms
 *   - plugin_keycloak_client: clients (+ kc uuid & secret)
 *   - plugin_keycloak_redirect_url: redirect/post-logout URIs
 */

import type { Plugin } from '../../plugins/types.js';
import { ENTITY_METAS } from './keycloak-meta.js';
import { keycloakRoutes } from './keycloak-routes.js';
import { migrations } from './migrations.js';

const keycloakPlugin: Plugin = {
  name: 'keycloak',
  version: '0.1.0',
  entities: ENTITY_METAS.map((meta) => ({ meta })),
  routes: keycloakRoutes,
  migrations,
};

export default keycloakPlugin;
